function tenant_db_name(int $tenantId): string
{
    // A DB name may only hold safe characters, so map the int to a
    // deterministic zero-padded string; clamping keeps the output stable.
    $id = max(0, $tenantId);

    return 'tenant_' . str_pad((string) $id, 6, '0', STR_PAD_LEFT);
}

