function filter_by_tenant(array $rows, int $tenantId): array
{
    $result = [];

    foreach ($rows as $row) {
        // Scope strictly on the tenant_id column; rows missing the key
        // must never match (null !== $tenantId), so no row can leak in.
        if (($row['tenant_id'] ?? null) === $tenantId) {
            $result[] = $row;
        }
    }

    return $result;
}

